/**
 * Dynamic app config. Reads `app.json` as the base and overrides a few
 * fields based on the EAS build profile (passed via env var APP_VARIANT).
 *
 * Profiles:
 *  - "development" / "staging" → side-by-side APKs with their own name, icons
 *    (tinted background + label) and android.package, so they can coexist
 *    on-device with the preview build
 *  - anything else (preview / production / undefined) → use the base config
 *
 * Icons are generated by design/logo/app_icons.py.
 *
 * To add a new variant: extend the `variants` map below.
 */

const variants = {
  development: {
    name: 'HintVaders Dev',
    androidPackage: 'com.invaderhunter.app.dev',
    icon: './assets/images/icon-dev.png',
    adaptiveForeground: './assets/images/android-icon-foreground-dev.png',
    adaptiveBackground: './assets/images/android-icon-background-dev.png',
  },
  staging: {
    name: 'HintVaders Stag',
    androidPackage: 'com.invaderhunter.app.stag',
    icon: './assets/images/icon-stag.png',
    adaptiveForeground: './assets/images/android-icon-foreground-stag.png',
    adaptiveBackground: './assets/images/android-icon-background-stag.png',
  },
};

module.exports = ({ config }) => {
  const variantKey = process.env.APP_VARIANT;
  const variant = variantKey ? variants[variantKey] : null;
  if (!variant) return config;

  return {
    ...config,
    name: variant.name,
    icon: variant.icon,
    android: {
      ...(config.android ?? {}),
      package: variant.androidPackage,
      icon: variant.icon,
      adaptiveIcon: {
        ...(config.android?.adaptiveIcon ?? {}),
        foregroundImage: variant.adaptiveForeground,
        backgroundImage: variant.adaptiveBackground,
      },
    },
  };
};
